function normalizeEntities(entities, keyField = 'id') {
  return entities.reduce(
    (result, entity) => {
      const key = entity[keyField];
      result.byId[key] = entity;
      result.allIds.push(key);
      return result;
    },
    { byId: {}, allIds: [] }
  );
}

// Usage
const posts = [
  { id: 'p1', title: 'First Post' },
  { id: 'p2', title: 'Second Post' }
];

const normalized = normalizeEntities(posts);
// Result:
// {
//   byId: { p1: {...}, p2: {...} },
//   allIds: ['p1', 'p2']
// }

// Update a single user by ID
const updateUser = (usersState, userId, changes) => ({
  ...usersState,
  byId: {
    ...usersState.byId,
    [userId]: { ...usersState.byId[userId], ...changes }
  }
});

// Delete a post
const removePost = (postsState, postId) => {
  const { [postId]: removed, ...remaining } = postsState.byId;
  return {
    byId: remaining,
    allIds: postsState.allIds.filter(id => id !== postId)
  };
};

// Add a new comment
const addComment = (commentsState, newComment) => ({
  byId: { ...commentsState.byId, [newComment.id]: newComment },
  allIds: [...commentsState.allIds, newComment.id]
});

// Selector to get a post with author and comments populated
const selectPostWithDetails = (state, postId) => {
  const post = state.posts.byId[postId];
  if (!post) return null;

  const author = state.users.byId[post.authorId];
  const comments = post.commentIds
    .map(id => state.comments.byId[id])
    .map(comment => ({
      ...comment,
      author: state.users.byId[comment.authorId]
    }));

  return { ...post, author, comments };
};
